package seneca.parte1;
import java.time.*;
import java.nio.file.*;
import java.util.*;
public final class PruebasProyecto2Referencia {
    private static int n;
    private static void ok(boolean b){if(!b)throw new AssertionError("Fallo en verificacion "+(n+1));n++;}
    private static void error(Runnable r){try{r.run();throw new AssertionError("Se esperaba rechazo "+(n+1));}catch(IllegalArgumentException e){n++;}}
    private static class Caso {
        ClubSeneca c=new ClubSeneca();Administrador a=c.crearAdministradorInicial("admin","clave");
        Deporte d=new Deporte("tenis");Categoria cat=new Categoria("intermedio");LocalDate fecha=LocalDate.of(2030,1,7);
        Socio s=socio("s1"),s2=socio("s2"),s3=socio("s3"),s4=socio("s4"),s5=socio("s5");
        Estudiante est=new Estudiante("est","clave","123",true), no=new Estudiante("no","clave","124",false);
        Externo ext=new Externo("ext","clave","Externo","01");Entrenador emp=new Entrenador();
        Caso(){c.registrarUsuario(a,est);c.registrarUsuario(a,no);c.registrarUsuario(a,ext);emp.setLogin("emp");emp.setPassword("clave");emp.setCodigoDescuento("EMP");c.registrarUsuario(a,emp);}
        Socio socio(String login){Socio x=new Socio();x.setLogin(login);x.setPassword("clave");x.setEdad(20);c.registrarUsuario(a,x);return x;}
        TorneoRecreativo rec(String id,int cupos,ModalidadTorneo m){TorneoRecreativo t=new TorneoRecreativo(id,id,fecha,cupos,d,cat,m,.15);c.crearTorneo(a,t);return t;}
        TorneoCompetitivo comp(String id,int cupos){TorneoCompetitivo t=new TorneoCompetitivo(id,id,fecha,cupos,d,cat,ModalidadTorneo.INDIVIDUAL,100);c.crearTorneo(a,t);return t;}
        InscripcionTorneo ins(Torneo t,Usuario u){return c.inscribirTorneo(u,t.getId(),p(u));}
        void liberar(Torneo t){c.liberarCuposTorneo(a,t.getId());}
        void iniciar(Torneo t){c.iniciarTorneo(a,t.getId());}
        void terminar(Torneo t,Usuario ganador){for(EncuentroTorneo e:t.getEncuentros()){boolean gana=e.getLocal().contiene(ganador)||!e.getVisitante().contiene(ganador);c.registrarResultadoTorneo(a,t.getId(),e.getId(),gana?2:0,gana?0:2);}c.finalizarTorneo(a,t.getId());}
    }
    private static ParticipanteTorneo p(Usuario u){return ParticipanteTorneo.jugadores(List.of(u));}
    public static void cupos(){Caso x=new Caso();TorneoRecreativo t=x.rec("t",6,ModalidadTorneo.INDIVIDUAL);ok(t.calcularCuposPreferenciales()==2);ok(t.cuposRegularesDisponibles()==4);x.c.configurarRankingTorneo(x.a,"t",List.of(p(x.s).getId(),p(x.s2).getId(),p(x.s3).getId()));ok(!x.ins(t,x.s3).isPreferencial());x.ins(t,x.s4);x.ins(t,x.s5);x.ins(t,x.est);error(()->x.ins(t,x.ext));ok(x.ins(t,x.s).isPreferencial());ok(t.calcularCuposDisponibles()==1);error(()->x.ins(t,x.s));error(()->x.c.desinscribirTorneo(x.ext,"t",p(x.s).getId()));x.c.desinscribirTorneo(x.s,"t",p(x.s).getId());ok(t.calcularCuposDisponibles()==2);ok(!t.getInscripciones().getLast().isActiva());ok(x.ins(t,x.s2).isPreferencial());x.liberar(t);ok(t.cuposRegularesDisponibles()==1);ok(!x.ins(t,x.ext).isPreferencial());ok(t.calcularCuposDisponibles()==0);error(()->x.ins(t,x.s));x.rec("otro",4,ModalidadTorneo.INDIVIDUAL);ok(x.c.getTorneos().consultarTorneos().size()==2);error(()->x.rec("otro",4,ModalidadTorneo.INDIVIDUAL));}
    public static void roles(){Caso x=new Caso();TorneoCompetitivo t=x.comp("c",5);x.liberar(t);ok(x.ins(t,x.est).getValorInscripcion()==100);ok(x.ins(t,x.ext).getValorInscripcion()==100);error(()->x.ins(t,x.no));ok(x.ins(t,x.emp).getValorInscripcion()==0);ok(t.calcularRecaudacion()==200);x.c.desinscribirTorneo(x.est,"c",p(x.est).getId());ok(t.calcularRecaudacion()==100);x.iniciar(t);error(()->x.c.desinscribirTorneo(x.ext,"c",p(x.ext).getId()));error(()->x.ins(t,x.s));error(()->x.c.finalizarTorneo(x.a,"c"));x.terminar(t,x.emp);ok(t.getPremios().isEmpty());ok(t.getEstado()==EstadoTorneo.FINALIZADO);TorneoCompetitivo u=x.comp("turno",3);x.liberar(u);x.c.getAdministrativo().crearTurno(x.a,x.emp,"lunes","08:00","10:00");ok(x.fecha.getDayOfWeek()==DayOfWeek.MONDAY);error(()->x.ins(u,x.emp));}
    public static void premios(){Caso x=new Caso();TorneoCompetitivo t=x.comp("c",3);x.liberar(t);x.ins(t,x.s);x.ins(t,x.emp);x.ins(t,x.ext);x.iniciar(t);ok(t.getEncuentros().size()==3);error(()->x.c.registrarResultadoTorneo(x.a,"c","c-1",-1,2));error(()->x.c.registrarResultadoTorneo(x.a,"c","c-1",1,1));x.terminar(t,x.s);ok(t.getPremios().size()==1);ok(t.getPremios().getFirst().getMonto()==200);ok(t.getPremios().getFirst().getParticipante().contiene(x.s));ok(t.consultarPosiciones().getFirst().getPosicionFinal()==1);x.c.marcarPremioEntregado(x.a,"c");ok(t.getPremios().getFirst().isEntregado());error(()->x.c.marcarPremioEntregado(x.a,"c"));error(()->x.c.finalizarTorneo(x.a,"c"));error(()->x.c.registrarResultadoTorneo(x.a,"c","c-1",2,1));}
    public static void bonos() throws Exception {Caso x=new Caso();TorneoRecreativo t=x.rec("r",3,ModalidadTorneo.INDIVIDUAL);x.liberar(t);ok(x.ins(t,x.s).getValorInscripcion()==0);x.ins(t,x.s2);x.iniciar(t);x.terminar(t,x.s);BonoDescuento b=x.c.getTorneos().consultarBonos(x.s).getFirst();ok(b.estaDisponible());ok(x.c.getTorneos().consultarBonos(x.s2).isEmpty());Snack snack=new Snack("mani");snack.setNombre("snack");snack.setPrecio(100);snack.setActivo(true);x.c.registrarProducto(x.a,snack);error(()->x.c.comprarConBono(x.s2,b.getCodigo(),"CAFETERIA",Map.of(snack,1),0,true));error(()->x.c.comprarConBono(x.s,b.getCodigo(),"CAFETERIA",Map.of(snack,1),0,false));ok(b.estaDisponible());Venta v=x.c.comprarConBono(x.s,b.getCodigo(),"CAFETERIA",Map.of(snack,1),0,true);ok(v.getDescuento()==15);ok(!b.estaDisponible());error(()->x.c.comprarConBono(x.s,b.getCodigo(),"CAFETERIA",Map.of(snack,1),0,true));Path f=Files.createTempFile("seneca2",".dat");try{x.c.guardar(f);ClubSeneca y=ClubSeneca.cargar(f);Usuario s=y.autenticar("s1","clave");ok(s!=null);ok(!y.getTorneos().consultarBonos(s).getFirst().estaDisponible());ok(y.getTorneos().buscarTorneo("r").getEstado()==EstadoTorneo.FINALIZADO);ok(y.getTorneos().buscarTorneo("r").getEncuentros().size()==1);}finally{Files.deleteIfExists(f);}}
    public static void modalidades(){Caso x=new Caso();TorneoRecreativo t=x.rec("dobles",4,ModalidadTorneo.DOBLES);x.liberar(t);error(()->x.ins(t,x.s));error(()->ParticipanteTorneo.jugadores(List.of(x.s,x.s)));ParticipanteTorneo d=ParticipanteTorneo.jugadores(List.of(x.s,x.est));x.c.inscribirTorneo(x.s,"dobles",d);error(()->x.c.inscribirTorneo(x.s2,"dobles",ParticipanteTorneo.jugadores(List.of(x.s2,x.est))));error(()->x.c.inscribirTorneo(x.emp,"dobles",ParticipanteTorneo.jugadores(List.of(x.emp,x.s2))));x.c.inscribirTorneo(x.s3,"dobles",ParticipanteTorneo.jugadores(List.of(x.s3,x.ext)));x.iniciar(t);x.terminar(t,x.s);ok(t.getBonos().size()==2);Deporte fut=new Deporte("futbol");Categoria mayor=new Categoria("mayores");TorneoRecreativo te=new TorneoRecreativo("e","equipos",x.fecha,4,fut,mayor,ModalidadTorneo.EQUIPOS,.1);x.c.crearTorneo(x.a,te);x.liberar(te);Equipo e=new Equipo("A",10,fut,mayor,new ArrayList<>());x.c.crearEquipo(x.a,e);x.c.inscribirEquipo(x.s,e,"delantero",1);error(()->x.c.inscribirTorneo(x.s,"e",ParticipanteTorneo.equipo(e)));for(int j=2;j<=7;j++)x.c.inscribirEquipo(x.socio("equipo"+j),e,"defensa",j);ok(x.c.inscribirTorneo(x.s,"e",ParticipanteTorneo.equipo(e)).isActiva());error(()->x.c.inscribirTorneo(x.s2,"e",ParticipanteTorneo.equipo(e)));}
    public static void elo(){Caso x=new Caso();x.c.inscribirAcademia(x.s,x.d,"intermedio").setRankingELO(1300);x.c.inscribirAcademia(x.s2,x.d,"intermedio").setRankingELO(1200);x.c.inscribirAcademia(x.s3,x.d,"avanzado").setRankingELO(1600);TorneoRecreativo t=x.rec("elo",4,ModalidadTorneo.INDIVIDUAL);x.c.configurarRankingElo(x.a,"elo");ok(t.getRanking().equals(List.of(p(x.s).getId(),p(x.s2).getId())));ok(x.ins(t,x.s).isPreferencial());ok(!x.ins(t,x.s2).isPreferencial());error(()->x.ins(t,x.s3));Administrador falso=new Administrador();falso.setLogin("admin");error(()->x.c.iniciarTorneo(falso,"elo"));}
    public static void main(String[] args)throws Exception{n=0;cupos();roles();premios();bonos();modalidades();elo();System.out.println("PROYECTO 2 REFERENCIA: "+n+" verificaciones superadas");}
}